import itertools
def tform(s):
    ts=set()
    for f in [(lambda y,x:(y,x)),(lambda y,x:(x,y))]:
        for sy in (1,-1):
            for sx in (1,-1):
                pts=[f(sy*y,sx*x) for y,x in s]
                my=min(p[0] for p in pts); mx=min(p[1] for p in pts)
                ts.add(tuple(sorted((p[0]-my,p[1]-mx) for p in pts)))
    return ts
def canon(s):
    return min(tform(s))
