def iso(G,bg):
    sh=allshapes(G,bg)
    allcells=[p for c,s in sh for p in s]
    res=[]
    for c,s in sh:
        s=set(s)
        others=[p for p in allcells if p not in s]
        m=min(abs(p[0]-q[0])+abs(p[1]-q[1]) for p in s for q in others)
        res.append((m,c,sorted(s)[0],len(s)))
    return sorted(res,reverse=True)
